<script setup>
import { ref, computed, onMounted } from 'vue';
import { api } from '../../services/api.js';
import { money, whatsappUrl } from '../../services/format.js';
import PlatformLayout from '../../layouts/PlatformLayout.vue';
import Icon from '../../components/Icon.vue';
const config = ref(null), error = ref('');
const home = computed(()=>config.value?.home || {});
const plans = computed(()=>config.value?.plans || []);
const benefits = computed(()=>Array.isArray(home.value.benefits) ? home.value.benefits : [
  {icon:'palette',title:'Una tienda que se siente tuya',description:'Elegí colores, organizá tu catálogo y diseñá cada paso de la compra.'},
  {icon:'credit-card',title:'Más formas de decir que sí',description:'Cobrá con Mercado Pago, transferencia o efectivo. Vos elegís cómo entregar.'},
  {icon:'package',title:'Todo en un mismo lugar',description:'Administrá productos, stock y pedidos desde un panel pensado para tu día a día.'}
]);
async function load(){error.value='';try{config.value=await api.get('/public/config');}catch(e){error.value=e.message;}}
onMounted(load);
</script>
<template>
<PlatformLayout>
  <section class="home-hero">
